"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def action_deltas(env, actions: Sequence[int] = ACTIONS) -> Dict[int, dict]:
    base = arr(env.frame()).copy()
    out = {}
    for action in actions:
        clone = env.clone()
        clone.step(action)
        out[int(action)] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence[int]):
    clone = env.clone()
    for action in actions:
        if clone.terminal():
            break
        clone.step(int(action))
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }


def changed_signature(env, actions: Sequence[int], cell: int = 4):
    before = block_signatures(env.frame(), cell)
    clone = replay(env, actions)
    after = block_signatures(clone.frame(), cell)
    return {k: (before.get(k), after.get(k)) for k in sorted(set(before) | set(after))
            if before.get(k) != after.get(k)}


def bounded_bfs(env, goal_fn, actions: Sequence[int] = (UP, DOWN, LEFT, RIGHT, USE),
                key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Generic clone BFS over observational keys. Use small max_states first."""
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()
    start_key = key_fn(env)
    q = deque([(env.clone(), [])])
    seen = {start_key}
    while q and len(seen) <= max_states:
        node, path = q.popleft()
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth:
            continue
        for action in actions:
            child = node.clone()
            child.step(int(action))
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            q.append((child, path + [int(action)]))
    return None


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(int(action))
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        for action in action_fn(node):
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

def _selected_center(env):
    frame = arr(env.frame())
    points = list(zip(*((frame == 0).nonzero())))
    if len(points) != 1:
        raise ValueError("no unique selection cursor")
    return int(points[0][0]), int(points[0][1])


def _selection_cycle(env, limit=12):
    """Centers of every selectable object, in the order USE cycles them."""
    scout = env.clone()
    centers = []
    first = None
    while True:
        center = _selected_center(scout)
        if first is None:
            first = center
        elif center == first:
            return centers
        centers.append(center)
        if len(centers) > limit:
            raise ValueError("selection cycle did not close")
        scout.step(USE)


def _park_all(env, direction, count, distance):
    """Push every selectable object off the board and return the bare frame."""
    scout = env.clone()
    for index in range(count):
        if index:
            scout.step(USE)
        for _ in range(distance):
            scout.step(direction)
    return arr(scout.frame())


def _survey_markers_and_swatches(env, count, distance, ring_color,
                                 border_color):
    """Ring markers and paint swatches, seen with the movable shapes parked."""
    markers, swatches = {}, {}
    for direction in (UP, DOWN, LEFT, RIGHT):
        frame = _park_all(env, direction, count, distance)
        background = _most_common(int(value) for value in frame.flat)
        for blob in connected_components(frame, colors=(ring_color,), min_area=8):
            if blob.size != (3, 3) or blob.area != 8:
                continue
            point = (blob.bbox[0] + 1, blob.bbox[1] + 1)
            value = int(frame[point])
            if value not in (ring_color, background):
                markers[point] = value
        for blob in connected_components(frame, colors=(border_color,), min_area=12):
            r0, c0, r1, c1 = blob.bbox
            if r1 - r0 < 3 or c1 - c0 < 3:
                continue
            cells = {
                (row, col)
                for row in range(r0 + 1, r1)
                for col in range(c0 + 1, c1)
                if int(frame[row, col]) not in (background, border_color)
            }
            values = {int(frame[point]) for point in cells}
            if len(values) == 1:
                swatches[values.pop()] = cells
    return markers, swatches


def _shape_offsets(env, index, count, distance):
    """Cell offsets of one selectable shape, with the others parked away."""
    scout = env.clone()
    for other in range(count):
        if other != index:
            for _ in range(distance):
                scout.step(UP)
        scout.step(USE)
    for _ in range(index):
        scout.step(USE)

    center = _selected_center(scout)
    before = arr(scout.frame()).copy()
    background = _most_common(int(value) for value in before.flat)
    frames = []
    votes = []
    for action in (UP, DOWN, LEFT, RIGHT):
        moved = scout.clone()
        moved.step(action)
        after = arr(moved.frame())
        frames.append(after)
        votes.extend(
            int(before[row, col])
            for row, col in zip(*((before != after).nonzero()))
            if int(after[row, col]) == background
            and int(before[row, col]) not in (0, background)
        )
    if not votes:
        raise ValueError("selected shape did not move")
    shape_color = _most_common(votes)

    # A shape cell need not vacate to the background: it may uncover a marker
    # it was hiding, so track every cell that stops being the shape colour.
    offsets = set()
    for after in frames:
        offsets.update(
            (int(row) - center[0], int(col) - center[1])
            for row, col in zip(*((before != after).nonzero()))
            if int(before[row, col]) == shape_color
        )
    offsets.discard((0, 0))

    rows, cols = before.shape[:2]
    complete = set(offsets)
    for row_offset, col_offset in list(offsets):
        for mirror in ((-row_offset, col_offset), (row_offset, -col_offset),
                       (-row_offset, -col_offset)):
            row, col = center[0] + mirror[0], center[1] + mirror[1]
            if not (0 <= row < rows and 0 <= col < cols):
                complete.add(mirror)
    return center, shape_color, complete


def _swatch_hit(offsets, center, swatches):
    cells = {(center[0] + dr, center[1] + dc) for dr, dc in offsets}
    hits = [color for color, swatch in swatches.items()
            if not swatch.isdisjoint(cells)]
    if len(hits) == 1:
        return hits[0]
    return "blocked" if hits else None


def _paint_routes(offsets, start, start_color, swatches, step, rows, cols):
    """BFS over (center, paint colour) states on the movement lattice."""
    hits = {
        (row, col): _swatch_hit(offsets, (row, col), swatches)
        for row in range(start[0] % step, rows, step)
        for col in range(start[1] % step, cols, step)
    }
    previous = {(start, start_color): None}
    queue = deque([(start, start_color)])
    while queue:
        state = queue.popleft()
        (row, col), color = state
        for dr, dc in ((-step, 0), (step, 0), (0, -step), (0, step)):
            point = (row + dr, col + dc)
            hit = hits.get(point, "blocked")
            if hit == "blocked":
                continue
            following = (point, color if hit is None else hit)
            if following in previous:
                continue
            previous[following] = state
            queue.append(following)
    return previous


def _route_centers(previous, state):
    path = []
    while state is not None:
        path.append(state[0])
        state = previous[state]
    return path[::-1]
def paint_shapes_at_swatches_to_cover_ring_markers(
        env, ring_color=4, station_border_color=2):
    """Cover every ring marker with a shape recoloured by a paint swatch.

    Unlike the earlier cover legs, a shape is repainted whenever ANY of its
    cells touches a swatch, so the route to a placement is searched too, not
    just the placement itself.
    """
    frame = arr(env.frame())
    rows, cols = frame.shape[:2]
    rings = [
        blob
        for blob in connected_components(frame, colors=(ring_color,), min_area=8)
        if blob.size == (3, 3) and blob.area == 8
    ]
    if not rings:
        raise ValueError("no ring markers found")
    step = rings[0].size[0]
    starts = _selection_cycle(env)
    distance = max(rows, cols) // step + 1

    markers, swatches = _survey_markers_and_swatches(
        env, len(starts), distance, ring_color, station_border_color)
    if not markers or not swatches:
        raise ValueError("no markers or paint swatches found")
    remaining = set(markers)

    plans = []
    for index in range(len(starts)):
        center, start_color, offsets = _shape_offsets(
            env, index, len(starts), distance)
        previous = _paint_routes(
            offsets, center, start_color, swatches, step, rows - 1, cols)
        best = {}
        for point, color in previous:
            covered = frozenset(
                marker for marker in markers
                if (marker[0] - point[0], marker[1] - point[1]) in offsets
            )
            if not covered or {markers[m] for m in covered} != {color}:
                continue
            path = _route_centers(previous, (point, color))
            if covered not in best or len(path) < len(best[covered]):
                best[covered] = path
        if not best:
            raise ValueError(f"shape {index} cannot cover a marker group")
        plans.append(sorted(best.items(), key=lambda item: len(item[1])))

    chosen = None

    def search(index, covered, picked, cost):
        nonlocal chosen
        if chosen is not None and cost >= chosen[0]:
            return
        if index == len(plans):
            if covered == remaining:
                chosen = (cost, list(picked))
            return
        for group, path in plans[index]:
            picked.append(path)
            search(index + 1, covered | group, picked, cost + len(path))
            picked.pop()

    search(0, set(), [], 0)
    if chosen is None:
        raise ValueError("no painted placement covers every marker")

    for index, path in enumerate(chosen[1]):
        if index:
            env.step(USE)
        for current, following in zip(path, path[1:]):
            _move_on_lattice(
                env, following[0] - current[0], following[1] - current[1], step)


def deform_selected_shapes_to_colored_ring_axes(env, ring_color=4):
    """Use barriers to reshape an outline and cross onto their coloured rings."""
    frame = arr(env.frame())
    rings = [
        blob
        for blob in connected_components(frame, colors=(ring_color,), min_area=8)
        if blob.size == (3, 3) and blob.area == 8
    ]
    if len(rings) != 8:
        raise ValueError("expected eight coloured ring markers")

    targets = defaultdict(list)
    for ring in rings:
        center = (ring.bbox[0] + 1, ring.bbox[1] + 1)
        targets[int(frame[center])].append(center)

    rectangle_groups = []
    axis_groups = []
    for color, points in targets.items():
        row_counts = Counter(row for row, _ in points)
        col_counts = Counter(col for _, col in points)
        if len(points) != 4:
            continue
        if len(row_counts) == 2 and len(col_counts) == 2:
            rectangle_groups.append((color, points))
        elif (
            len(row_counts) == 3
            and len(col_counts) == 3
            and max(row_counts.values()) == 2
            and max(col_counts.values()) == 2
        ):
            axis_groups.append((color, points))
    if len(rectangle_groups) != 1 or len(axis_groups) != 1:
        raise ValueError("could not identify rectangle and cross ring targets")

    step = rings[0].size[0]
    _, rectangle = rectangle_groups[0]
    rectangle_rows = sorted({row for row, _ in rectangle})
    rectangle_cols = sorted({col for _, col in rectangle})
    _, axes = axis_groups[0]
    axis_rows = Counter(row for row, _ in axes)
    axis_cols = Counter(col for _, col in axes)
    target_row = next(row for row, count in axis_rows.items() if count == 2)
    target_col = next(col for col, count in axis_cols.items() if count == 2)

    signature = (
        rectangle_rows[1] - rectangle_rows[0],
        rectangle_cols[1] - rectangle_cols[0],
        sorted(row - target_row for row, col in axes if col == target_col),
        sorted(col - target_col for row, col in axes if row == target_row),
    )
    expected = (
        9 * step,
        3 * step,
        [-step, 6 * step],
        [-step, 6 * step],
    )
    if signature != expected:
        raise ValueError("unsupported deformable ring geometry")

    square_maneuvers = (
        (-3 * step, 0),
        (0, 4 * step),
        (-8 * step, 0),
        (0, 9 * step),
        (10 * step, 0),
    )
    cross_maneuvers = (
        (-2 * step, 0),
        (0, -7 * step),
        (3 * step, 0),
        (0, 3 * step),
        (-3 * step, 0),
        (0, -5 * step),
        (8 * step, 0),
        (-6 * step, 0),
    )

    def execute(node):
        follow_lattice_maneuvers(node, square_maneuvers, step)
        node.step(USE)
        follow_lattice_maneuvers(node, cross_maneuvers, step)

    execute_verified_completion_route(
        env, execute, "deformation route did not cover all ring axes"
    )

def probe(env):
    with open("checkpoint.json") as handle:
        for action in json.load(handle)["final_path"]:
            env.step(action)

    root = env.clone()
    root.step(5)
    for _ in range(22):
        root.step(1)
    root.step(5)

    queue = deque([(root, [])])
    seen = {arr(root.frame()).tobytes()}
    while queue and len(seen) < 12000:
        node, path = queue.popleft()
        cursor = list(zip(*((arr(node.frame()) == 0).nonzero())))[0]
        if cursor[1] <= 30 and cursor[0] >= 27:
            shape = selected_shape(node)
            if shape is not None:
                center, color, offsets = shape
                occupied = {
                    (center[0] + row, center[1] + col) for row, col in offsets
                }
                if color in TARGETS and TARGETS[color] <= occupied:
                    print("FOUND", color, len(path), path)
                    print("shape", center, len(offsets), sorted(offsets))
                    return
        if len(path) >= 65:
            continue
        for action in (1, 2, 3, 4):
            child = node.clone()
            child.step(action)
            key = arr(child.frame()).tobytes()
            if key not in seen:
                seen.add(key)
                queue.append((child, path + [action]))
    print("NOT_FOUND", len(seen), "queued", len(queue))


print("RUN", A.run_program("re86", probe))
